import unreal_engine as ue

def name(obj):
    if not obj:
        return None
    try:
        return obj.get_name()
    except Exception:
        return str(obj)

def label(actor):
    try:
        return actor.get_actor_label()
    except Exception:
        return name(actor)

def vec(v):
    try:
        return {'x': round(v.x, 2), 'y': round(v.y, 2), 'z': round(v.z, 2)}
    except Exception:
        return str(v)

def prop(obj, key):
    try:
        return obj.get_property(key)
    except Exception as e:
        return 'ERR:' + str(e)

def simple(v):
    if v is None:
        return None
    if isinstance(v, (str, int, float, bool)):
        return v
    if isinstance(v, (list, tuple)):
        return [simple(x) for x in v]
    try:
        return vec(v)
    except Exception:
        pass
    try:
        return name(v)
    except Exception:
        return str(v)

selected = ue.editor_get_selected_actors()
world = ue.get_editor_world()
actors = world.all_actors()
result = {'selected': [], 'spawners': [], 'monsters': [], 'waypoint_like': [], 'counts': {'actors': len(actors)}}

interesting_spawner_props = ['UsePathPoint','CachePositions','bUseNavMesh','Range','Height','MobConfig','MaxAliveCount','MinSpawnCount','MaxSpawnCount','MobCountPerSpawn','SpawnCD','SpawnerContrMode','CampID']
interesting_mob_props = ['AutoPossessAI','AIControllerClass','Controller','CharacterMovement','MoveControlComp','BehaviorControlComp','GeneralCampID','UGCGeneralMoveSpeedScale','bUseControllerRotationYaw']

for a in selected:
    item = {'label': label(a), 'name': name(a), 'class': name(a.get_class()), 'location': vec(a.get_actor_location())}
    props = {}
    for p in interesting_spawner_props:
        props[p] = simple(prop(a, p))
    # include any properties containing waypoint/path names
    try:
        for p in a.properties():
            low = p.lower()
            if ('path' in low or 'way' in low or 'point' in low or 'cache' in low or 'nav' in low) and p not in props:
                props[p] = simple(prop(a, p))
    except Exception as e:
        props['properties_error'] = str(e)
    item['props'] = props
    result['selected'].append(item)

for a in actors:
    cls = name(a.get_class()) or ''
    lab = label(a) or ''
    if 'Spawner' in cls or 'Spawner' in lab:
        item = {'label': lab, 'name': name(a), 'class': cls, 'location': vec(a.get_actor_location()), 'props': {}}
        for p in interesting_spawner_props:
            item['props'][p] = simple(prop(a, p))
        result['spawners'].append(item)
    if 'BaseMonse' in cls or 'Mob' in cls or 'Monster' in cls or 'Mons' in cls:
        item = {'label': lab, 'name': name(a), 'class': cls, 'location': vec(a.get_actor_location()), 'props': {}}
        for p in interesting_mob_props:
            item['props'][p] = simple(prop(a, p))
        try:
            ctrl = a.get_property('Controller')
            item['controller_class'] = name(ctrl.get_class()) if ctrl else None
        except Exception as e:
            item['controller_error'] = str(e)
        try:
            move = a.get_property('CharacterMovement')
            item['movement_mode'] = simple(move.get_property('MovementMode')) if move else None
            item['max_walk_speed'] = simple(move.get_property('MaxWalkSpeed')) if move else None
        except Exception as e:
            item['movement_error'] = str(e)
        result['monsters'].append(item)
    if any(k in cls.lower() or k in lab.lower() for k in ['waypoint','way','path','targetpoint','patrol']):
        result['waypoint_like'].append({'label': lab, 'name': name(a), 'class': cls, 'location': vec(a.get_actor_location())})

