from unreal_engine.classes import BaseMonse_Child_C

def name(obj):
    if not obj: return None
    try: return obj.get_name()
    except Exception: return str(obj)

def simple(v):
    if v is None: return None
    if isinstance(v,(str,int,float,bool)): return v
    if isinstance(v,(list,tuple)): return [simple(x) for x in v]
    try: return name(v)
    except Exception: return str(v)

def prop(o,p):
    try: return o.get_property(p)
    except Exception as e: return 'ERR:' + str(e)

cdo = BaseMonse_Child_C.get_cdo()
result = {'class':'BaseMonse_Child_C','components':[], 'logic_part_manager':{} }
try:
    comps = cdo.get_components_by_class(None)
except Exception as e:
    comps = []
    result['get_components_error'] = str(e)
try:
    # fallback: inspect CDO properties that are component refs
    for p in cdo.properties():
        v = prop(cdo,p)
        nv = name(v)
        if nv and ('Comp' in nv or 'Part' in nv or 'Move' in nv or 'Behavior' in nv or 'Logic' in nv or 'Waypoint' in nv):
            result['components'].append({'prop':p, 'obj':nv, 'class':name(v.get_class()) if hasattr(v,'get_class') else None})
except Exception as e:
    result['props_error'] = str(e)
lpm = prop(cdo, 'LogicPartManagerComp')
result['logic_part_manager']['object'] = simple(lpm)
if not isinstance(lpm, str) and lpm:
    try:
        result['logic_part_manager']['class'] = name(lpm.get_class())
        result['logic_part_manager']['matching_props'] = [p for p in lpm.properties() if any(k in p.lower() for k in ['part','logic','way','follow','array','config'])]
        result['logic_part_manager']['prop_values'] = {p: simple(prop(lpm,p)) for p in result['logic_part_manager']['matching_props']}
    except Exception as e:
        result['logic_part_manager']['error'] = str(e)
__askq_result = result
